CustomField.formula:
if( isNull(Deployment_Date__c ), "Manual",
Text(Year( DateValue(Deployment_Date__c ))) & "-" & 
IF(Month( DateValue(Deployment_Date__c ))>=10, Text( Month(DateValue(Deployment_Date__c ))), "0"&Text(Month(DateValue( Deployment_Date__c )))) & "-" & 
IF(Day(DateValue( Deployment_Date__c ))>=10, Text( Day(DateValue( Deployment_Date__c ))), "0"&Text(Day(DateValue( Deployment_Date__c ))))

)
